with e as (select $1::jsonb as j), achado as (select c.id from serena_contatos c, e where (nullif(j->>'contato_id','') is not null and c.id = (j->>'contato_id')::uuid) or (nullif(j->>'telefone','') is not null and c.telefone = j->>'telefone') or (nullif(j->>'session_site','') is not null and c.session_site = j->>'session_site') or (nullif(j->>'email','') is not null and c.email = j->>'email') order by (nullif(j->>'contato_id','') is not null and c.id = (j->>'contato_id')::uuid) desc, c.atualizado_em desc limit 1), novo as (insert into serena_contatos (telefone,email,nome,session_site) select nullif(j->>'telefone',''), nullif(j->>'email',''), nullif(j->>'nome',''), nullif(j->>'session_site','') from e where not exists (select 1 from achado) returning id), alvo as (select id from achado union all select id from novo), a as (select (select id from alvo) as id), tel as (select regexp_replace(coalesce(e.j->>'telefone',''), '\D', '', 'g') as d from e), cemail as (select lower(coalesce(nullif(e.j->>'email',''), (select email from serena_contatos where id = (select id from a)), '')) as v from e) select (select id from a) as contato_id, (select nome from serena_contatos where id=(select id from a)) as nome, (select ia_pausada from serena_conversas where contato_id=(select id from a) order by aberta_em desc limit 1) as ia_pausada, coalesce((select jsonb_agg(jsonb_build_object('chave',chave,'valor',valor,'origem',origem)) from serena_fatos where contato_id=(select id from a)),'[]'::jsonb) as fatos, coalesce((select jsonb_agg(jsonb_build_object('papel',papel,'texto',texto)) from (select papel,texto,criado_em from serena_mensagens where contato_id=(select id from a) and texto is not null and papel in ('cliente','serena','humano') order by criado_em desc limit 20) h),'[]'::jsonb) as historico, (select valor from serena_config where chave='base_treinamento') as base, coalesce((select valor from serena_config where chave='system_prompt'),'') as prompt_extra, coalesce((select valor from serena_config where chave='modelo'),'claude-sonnet-4-5-20250929') as modelo, coalesce((select valor from serena_config where chave='max_tokens'),'1500') as max_tokens, coalesce((select valor from serena_config where chave='wpp_pausa_handoff_min'),'720')::int as pausa_handoff_min, coalesce((select valor from serena_config where chave='detectar_irritado'),'on') as detectar_irritado, coalesce((select valor from serena_config where chave='carrinho_via_serena'),'on') as carrinho_via_serena, coalesce((select valor from serena_config where chave='detectar_lacunas'),'on') as detectar_lacunas, coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'tipo', t.tipo, 'pedido', t.pedido, 'status', t.status, 'criado_em', t.criado_em) order by t.criado_em desc) from serena_trocas t where t.contato_id=(select id from a) and t.status in ('aberta','em_analise')), '[]'::jsonb) as trocas, coalesce((select jsonb_agg(et.etiqueta) from serena_etiquetas et where et.contato_id=(select id from a)),'[]'::jsonb) as etiquetas, (select jsonb_build_object('itens', ca.itens, 'total', ca.total, 'checkout_url', ca.checkout_url, 'coupon', ca.coupon, 'recusa_cartao', ca.recusa_cartao, 'boleto_pendente', ca.boleto_pendente, 'status', ca.status, 'criado_em', ca.criado_em) from carrinhos_abandonados ca, tel, cemail where ca.convertido_em is null and ca.criado_em > now() - interval '7 days' and ((tel.d <> '' and regexp_replace(coalesce(ca.whatsapp,''), '\D', '', 'g') = tel.d) or (cemail.v <> '' and lower(coalesce(ca.email,'')) = cemail.v)) order by ca.criado_em desc limit 1) as carrinho, coalesce((select jsonb_agg(jsonb_build_object('erro', left(x.texto_serena, 300), 'correcao', x.correcao, 'quando', x.criado_em)) from (select sc.* from serena_correcoes sc where sc.contato_id = (select id from a) or sc.criado_em > now() - interval '30 days' order by (sc.contato_id = (select id from a)) desc, sc.criado_em desc limit 8) x), '[]'::jsonb) as correcoes
